def table(a,cols=None):
    if cols is not None:a=a[cols]
    def fmt(v):
        if isinstance(v,(float,np.floating)):return f'{v:,.4f}' if np.isfinite(v) else '—'
        return str(v).replace('|','/').replace('\n',' ')
    return '\n'.join(['| '+' | '.join(a.columns)+' |','| '+' | '.join(['---']*len(a.columns))+' |']+['| '+' | '.join(map(fmt,x))+' |' for x in a.itertuples(index=False,name=None)])

